    return m.display_phone_number || '';
  } catch (e) { return ''; }
}

const ctx = $('🎥 Preparar Pedidos').first().json;
const raw = $json.choices?.[0]?.message?.content || '';
let r = {}; try { r = JSON.parse(raw); } catch (e) { const m = raw.match(/\{[\s\S]*\}/); try { r = m ? JSON.parse(m[0]) : {}; } catch (e2) { r = {}; } }
const lista = Array.isArray(r.pedidos) ? r.pedidos : [];
if (!lista.length) return [{ json: { ok: false, motivo: 'la IA no devolvió pedidos válidos', detalle: String($json.error?.message || raw).slice(0, 300) } }];
const pedidos = lista.slice(0, ctx.base.length).map((p, i) => ({
  ...ctx.base[i],
  titulo: String(p.titulo || '').trim(),
  objetivo: String(p.objetivo || '').trim(),
  tomas: (Array.isArray(p.tomas) ? p.tomas : []).slice(0, 4).map((t, k) => ({ orden: k + 1, que_grabar: String(t.que_grabar || '').trim(), segundos: Math.min(Math.max(Number(t.segundos) || 5, 2), 20), consejo: String(t.consejo || '').trim() })),
  duracion_total_seg: Math.min(Math.max(Number(p.duracion_total_seg) || 30, 15), 45),
  texto_en_pantalla: String(p.texto_en_pantalla || '').trim(),
  consejo_general: String(p.consejo_general || '').trim(),
  formato: 'vertical 9:16, MP4', idioma: ctx.idioma
}));
// Ruta pedida a G54 en el Éxodo (pedido 4). Mientras no exista, responde 404 y se devuelven los pedidos igual.
let guardado = false, motivo = ctx.dry_run ? 'prueba (dry_run): no se guardó nada' : '';
if (!ctx.dry_run) {
  try {
    await http({ method: 'POST', url: B + '/api/agent/rrss/pedidos-grabacion', headers: { Authorization: 'Bearer ' + AGENT }, body: { company_id: ctx.company_id, pedidos } });
    guardado = true; motivo = 'pedidos guardados en G54';
  } catch (e) { motivo = 'G54 todavía no tiene la ruta POST /api/agent/rrss/pedidos-grabacion (' + String(e.message || e).slice(0, 80) + ')'; }
}
return [{ json: { ok: true, guardado, motivo, company_id: ctx.company_id, pedidos } }];
